<script setup lang="ts">
import {computed,ref,reactive,watch,onBeforeUnmount} from 'vue';
import {ApiError} from './api';
import VisitHistory from './VisitHistory.vue';
import DeadlineEvidence from './DeadlineEvidence.vue';
import {projectCommitment} from './domain/commitment';
import {followupCopy} from './followup-i18n';
import {equal,validSource,validPreparation,validBody,validPending,validRecovery,recoveryKey,bytes,PREPARATION_LIMIT,RECOVERY_LIMIT,type PreparationPending} from './preparation';
import {preparationApi} from './preparation-api';
import {preparationCopy} from './preparation-i18n';
const props=defineProps<{lang:'zh'|'en';scope:string;allowed:boolean;externalBusy:boolean;externalPending:boolean;eventDirty:boolean;upgrade:boolean;commitments:any[];epoch:number}>();
const emit=defineEmits<{state:[value:{busy:boolean;pending:boolean;dirty:boolean}];denied:[]}>();
const t=computed(()=>preparationCopy[props.lang]),ft=computed(()=>followupCopy[props.lang]);
function eventTitle(type:string){return ({created:ft.value.explicit,amended:ft.value.amend,'progress-recorded':ft.value.progress,'reply-recorded':ft.value.reply,completed:ft.value.complete,reopened:ft.value.reopen} as Record<string,string>)[type]??type;}
function bindingText(b:any){return b?`${ft.value.scope} ${b.contentRevision} · ${props.lang==='zh'?'承诺版本':'Commitment revision'} ${b.commitmentRevision} · ${props.lang==='zh'?'交流版本':'Interaction revision'} ${b.visitRevision} · ${b.visitId}`:'';}
function eventWording(index:number){let text='';for(const e of (actual.value?.history??source.value.commitment.events).slice(0,index+1))if((e.type==='created'||e.type==='amended')&&typeof e.commitmentText==='string')text=e.commitmentText;return text;}
const cid=ref(''),visible=ref(false),source=ref<any>(null),saved=ref<any>(null),latest=ref<any>(null),history=ref<any[]>([]),pending=ref<PreparationPending|null>(null),busy=ref(false),checking=ref(false),blocked=ref(false),reviewed=ref(false),background=ref(false);
const draft=reactive({purposeText:'',materialLeads:[] as any[],changeReason:''});
const status=ref<''|'local'|'saved'|'failed'|'invalid'|'storage'|'blocked'|'pending'|'notfound'|'denied'|'eventDraft'>('');
const identity=computed(()=>{try{return JSON.parse(props.scope)[1]}catch{return ''}});
const current=computed(()=>props.commitments.find(c=>c.id===cid.value));
const actual=computed(()=>{const p=projectCommitment(latest.value?.source?.commitment??source.value?.commitment);return p.ok&&(!current.value||p.value.revision>=current.value.revision)?p.value:current.value;});
const complete=computed(()=>actual.value?.completionStatus==='completed'||source.value?.open===false||latest.value?.source?.open===false);
const dirty=computed(()=>!!cid.value&&(draft.purposeText!==(saved.value?.purposeText??'')||JSON.stringify(draft.materialLeads)!==JSON.stringify(saved.value?.materialLeads??[])||!!draft.changeReason));
const changed=computed(()=>!!latest.value&&(!equal(latest.value.source.binding,source.value?.binding)||(latest.value.preparation?.revision??null)!==(saved.value?.revision??null)));
const stopped=computed(()=>!props.allowed||props.upgrade||blocked.value||props.externalBusy||busy.value);
const writesStopped=computed(()=>stopped.value||props.externalPending||!!pending.value||complete.value||changed.value||!source.value);
let alive=true,sequence=0,timer:ReturnType<typeof setTimeout>|undefined,delay=1000,hydrating=false;
let abort:AbortController|null=null;
function stop(){if(timer)clearTimeout(timer);timer=undefined;abort?.abort();abort=null;}
function snapshot(){return {schemaVersion:1,scope:props.scope,cid:cid.value,source:source.value,saved:saved.value,draft:{...draft},pending:pending.value};}
function persist(){if(!cid.value||!source.value)return true;if(blocked.value)return false;try{const k=recoveryKey(props.scope),v=snapshot();if(!k||bytes(v)>RECOVERY_LIMIT)throw Error('BUDGET');const raw=JSON.stringify(v);sessionStorage.setItem(k,raw);if(sessionStorage.getItem(k)!==raw)throw Error('VERIFY');return true;}catch{status.value='storage';return false;}}
function token(){return {sequence,scope:props.scope,epoch:props.epoch,cid:cid.value};}
function same(x:ReturnType<typeof token>){return alive&&x.sequence===sequence&&x.scope===props.scope&&x.epoch===props.epoch&&x.cid===cid.value&&props.allowed&&!props.upgrade;}
function statusError(e:unknown){if(e instanceof ApiError&&(e.status===401||e.status===403||e.status===426)){status.value='denied';stop();if(e.status!==426)emit('denied');}else status.value='failed';}
function validateResponse(r:any){return validSource(r?.source,cid.value,identity.value)&&(r.preparation===null||validPreparation(r.preparation,cid.value,identity.value));}
async function refresh(){if(stopped.value||!cid.value)return;const x=token();busy.value=true;try{const r=await preparationApi<any>(`/v2/commitments/${cid.value}/preparation`);if(!same(x))return;if(!validateResponse(r))throw Error('INVALID');latest.value=r;reviewed.value=false;const h=await preparationApi<any[]>(`/v2/commitments/${cid.value}/preparation/history`);if(!same(x))return;if(!Array.isArray(h)||h.some(p=>!validPreparation(p,cid.value,identity.value)))throw Error('INVALID_HISTORY');history.value=h;status.value='';}catch(e){if(same(x))statusError(e);}finally{busy.value=false;}}
async function open(id:string){if(stopped.value||props.externalPending||pending.value)return false;if(props.eventDirty){status.value='eventDraft';return false;}if(id===cid.value&&source.value){visible.value=true;await refresh();return true;}if(dirty.value&&!window.confirm(t.value.discard))return false;if(!persist())return false;sequence++;stop();cid.value=id;source.value=null;saved.value=null;latest.value=null;history.value=[];Object.assign(draft,{purposeText:'',materialLeads:[],changeReason:''});visible.value=true;status.value='';const x=token();busy.value=true;try{const r=await preparationApi<any>(`/v2/commitments/${id}/preparation`);if(!same(x))return false;if(!validateResponse(r))throw Error('INVALID');source.value=r.source;saved.value=r.preparation;latest.value=r;Object.assign(draft,{purposeText:r.preparation?.purposeText??'',materialLeads:structuredClone(r.preparation?.materialLeads??[]),changeReason:''});if(r.preparation)source.value=r.preparation.sourceSnapshot;persist();}catch(e){if(same(x))statusError(e);return false;}finally{busy.value=false;}await refresh();return true;}
function rebind(){if(stopped.value||props.externalPending||pending.value||!reviewed.value||!latest.value||complete.value)return;source.value=latest.value.source;saved.value=latest.value.preparation;reviewed.value=false;persist();}
function body(){return {schemaVersion:1,sourceBinding:source.value?.binding,purposeText:draft.purposeText,materialLeads:JSON.parse(JSON.stringify(draft.materialLeads)),changeReason:draft.changeReason,expectedPreparationRevision:saved.value?.revision??null};}
function accept(r:any,p:PreparationPending){if(!validPreparation(r,p.cid,identity.value)||r.id!==(p.pid??r.id)||r.revision!==(p.body.expectedPreparationRevision??0)+1||!equal(r.sourceBinding,p.body.sourceBinding)||r.purposeText!==p.body.purposeText||!equal(r.materialLeads,p.body.materialLeads)||r.changeReason!==p.body.changeReason)throw Error('WRONG_RECEIPT');saved.value=r;history.value=[...history.value.filter(h=>h.revision!==r.revision),r].sort((a,b)=>a.revision-b.revision);source.value=r.sourceSnapshot;latest.value={source:source.value,preparation:r};pending.value=null;hydrating=true;draft.changeReason='';hydrating=false;status.value='saved';stop();persist();}
async function perform(recoveryRetry=false){const p=pending.value;if(!p||stopped.value||(!recoveryRetry&&props.externalPending)||!validPending(p,cid.value))return;if(!persist())return;const x=token();busy.value=true;status.value='pending';try{const r=await preparationApi<any>(p.path,p.method,p.body,p.key);if(same(x)&&pending.value?.key===p.key)accept(r,p);}catch(e){if(!same(x))return;statusError(e);if(e instanceof ApiError&&e.status<500&&![401,403,426].includes(e.status)){pending.value=null;persist();if(e.status===409){busy.value=false;await refresh();}}}finally{busy.value=false;schedule();}}
async function save(){if(writesStopped.value)return;const b=body();if(!validBody(b)||bytes(b)>PREPARATION_LIMIT){status.value='invalid';return;}pending.value={kind:'preparation',key:crypto.randomUUID(),cid:cid.value,pid:saved.value?.id??null,path:`/v2/commitments/${cid.value}/preparation`+(saved.value?'/'+saved.value.id:''),method:saved.value?'PUT':'POST',body:b};if(!persist())return;await perform();}
async function lookup(retry=false){const p=pending.value;if(!p||stopped.value||checking.value)return;const x=token();checking.value=true;abort=new AbortController();try{const r=await preparationApi<any>(`/v2/preparation-commands/${encodeURIComponent(p.key)}`,'GET',undefined,undefined,abort.signal);if(same(x)&&pending.value?.key===p.key)accept(r,p);}catch(e){if(!same(x)||pending.value?.key!==p.key)return;if(e instanceof ApiError&&e.status===404){status.value='notfound';if(retry&&!props.externalBusy)await perform(true);}else statusError(e);}finally{checking.value=false;abort=null;schedule();}}
function schedule(){if(timer)clearTimeout(timer);timer=undefined;if(!alive||!pending.value||!props.allowed||props.upgrade||blocked.value||document.visibilityState==='hidden')return;timer=setTimeout(()=>{timer=undefined;lookup();delay=Math.min(delay*2,15000)},delay);}
function resume(){delay=1000;schedule();}function pause(){stop();}
function add(){if(!writesStopped.value&&draft.materialLeads.length<5)draft.materialLeads.push({lineId:crypto.randomUUID(),name:'',sourceDescription:'',versionDescription:'',question:''});}
function remove(i:number){if(!writesStopped.value)draft.materialLeads.splice(i,1);}
function close(){if(busy.value||pending.value)return;persist();visible.value=false;}
watch([busy,pending,dirty],()=>emit('state',{busy:busy.value,pending:!!pending.value,dirty:dirty.value}),{flush:'sync',immediate:true});
watch(draft,()=>{if(!hydrating&&source.value){status.value='local';persist();}},{deep:true,flush:'sync'});
watch(()=>props.scope,()=>{sequence++;stop();hydrating=true;cid.value='';source.value=null;saved.value=null;latest.value=null;pending.value=null;history.value=[];visible.value=false;blocked.value=false;status.value='';Object.assign(draft,{purposeText:'',materialLeads:[],changeReason:''});try{const k=recoveryKey(props.scope);if(k){const raw=sessionStorage.getItem(k);if(raw!==null){if(new TextEncoder().encode(raw).length>RECOVERY_LIMIT)throw Error('BUDGET');const v=JSON.parse(raw);if(!validRecovery(v,props.scope))throw Error('INVALID');cid.value=v.cid;source.value=v.source;saved.value=v.saved;Object.assign(draft,v.draft);pending.value=v.pending;visible.value=true;status.value=v.pending?'pending':'local';}}}catch{blocked.value=true;status.value='blocked';}finally{hydrating=false;}schedule();},{immediate:true});
watch(()=>props.allowed,allowed=>{if(!allowed){sequence++;stop();status.value='denied';}else schedule();});
watch(()=>props.upgrade,value=>{if(value){stop();status.value='denied';}else schedule();});
function visibility(){document.visibilityState==='hidden'?pause():resume();}
window.addEventListener('pagehide',pause);window.addEventListener('pageshow',resume);document.addEventListener('visibilitychange',visibility);
onBeforeUnmount(()=>{alive=false;sequence++;stop();window.removeEventListener('pagehide',pause);window.removeEventListener('pageshow',resume);document.removeEventListener('visibilitychange',visibility);});
defineExpose({open,persist});
</script>
<template>
<p v-if="allowed&&(status==='eventDraft'||status==='blocked')" role="alert">{{t[status]}}</p>
<section v-show="visible&&allowed" id="preparation-panel" class="panel preparation-panel">
 <header><h2>{{t.title}}</h2><button type="button" :disabled="busy||!!pending" @click="close">{{t.close}}</button></header>
 <p v-if="status" id="preparation-status" role="status">{{t[status]}}</p><p v-if="externalBusy||externalPending">{{t.busy}}</p>
 <div v-if="pending" class="alert warning"><p>{{t.pending}}</p><p v-if="checking">{{t.checking}}</p><button id="preparation-lookup" :disabled="stopped||checking" @click="lookup()">{{t.lookup}}</button><button id="preparation-retry" :disabled="stopped||checking" @click="lookup(true)">{{t.retry}}</button></div>
 <template v-if="source"><p v-if="complete" id="preparation-readonly">{{t.readonly}}</p><p v-if="saved">{{t.savedVersion}}: <span id="preparation-id">{{saved.id}}</span> / <span id="preparation-revision">{{saved.revision}}</span></p><p v-else>{{t.missing}}</p>
 <button id="preparation-refresh" :disabled="stopped||!!pending" @click="refresh">{{t.refresh}}</button>
 <section v-if="changed" id="preparation-conflict" class="alert warning"><p>{{t.compare}}</p><h4>{{t.old}}</h4><p>{{bindingText(source.binding)}} · {{saved?.revision??'—'}}</p><p class="preserve-text">{{source.visit.notes}}</p><h4>{{t.latest}}</h4><p>{{bindingText(latest.source.binding)}} · {{latest.preparation?.revision??'—'}}</p><p class="preserve-text">{{latest.source.visit.notes}}</p><p v-if="latest.preparation" class="preserve-text">{{latest.preparation.purposeText}}</p><label><input id="preparation-reviewed" type="checkbox" v-model="reviewed" :disabled="stopped||!!pending||complete">{{t.confirm}}</label><button id="preparation-rebind" :disabled="!reviewed||stopped||!!pending||externalPending||complete" @click="rebind">{{t.rebind}}</button></section>
 <form @submit.prevent="save"><fieldset :disabled="writesStopped"><h3>{{t.purpose}}</h3><textarea id="preparation-purpose" v-model="draft.purposeText" rows="3"></textarea><p v-if="!draft.purposeText">{{t.emptyPurpose}}</p><h3>{{t.leads}}</h3><p>{{t.unverified}}</p><article v-for="(line,i) in draft.materialLeads" :key="line.lineId" class="preparation-lead"><label>{{t.name}}<input :id="'preparation-name-'+i" v-model="line.name"></label><label>{{t.source}}<textarea :id="'preparation-source-'+i" v-model="line.sourceDescription"></textarea></label><label>{{t.version}}<input :id="'preparation-version-'+i" v-model="line.versionDescription" :placeholder="t.unknown"></label><label>{{t.question}}<textarea :id="'preparation-question-'+i" v-model="line.question"></textarea></label><button type="button" @click="remove(i)">{{t.remove}}</button></article><button id="preparation-add-lead" type="button" :disabled="draft.materialLeads.length>=5" @click="add">{{t.add}}</button><label>{{t.reason}}<textarea id="preparation-reason" v-model="draft.changeReason"></textarea></label><p>{{t.boundary}}</p><button id="preparation-save" type="submit">{{t.save}}</button></fieldset></form>
 <section><h3>{{t.background}}</h3><p>{{t.binding}}: {{bindingText(source.binding)}}</p><h4>{{t.actual}}</h4><p>{{source.commitment.ownerId}} · {{complete?ft.completed:ft.open}}</p><DeadlineEvidence v-if="actual" :deadline="actual.deadline" :text="actual.commitmentText" :lang="lang"/><ol><li v-for="(e,index) in (actual?.history??source.commitment.events)" :key="e.eventId"><p>{{eventTitle(e.type)}} · {{e.recordedAt}} · {{ft.scope}} {{e.contentRevision}}</p><p class="preserve-text">{{e.commitmentText||e.text||e.reason}}</p><DeadlineEvidence v-if="e.deadline" :deadline="e.deadline" :text="eventWording(index)" :lang="lang"/><p v-if="e.status">{{e.status==='verified'?ft.verified:e.status==='in-progress'?ft.inProgress:ft.notStarted}}</p><p v-if="e.direction">{{e.direction==='from-customer'?ft.fromCustomer:ft.toCustomer}}</p></li></ol><button id="preparation-source-open" @click="background=true">{{t.visit}}</button><section v-if="background"><p class="preserve-text">{{source.visit.notes}}</p><p>{{source.visit.id}} · {{source.visit.revision}}</p><VisitHistory :visit="source.visit" role="rep" :lang="lang" :epoch="epoch" @denied="emit('denied')"/><button id="preparation-source-close" @click="background=false">{{t.back}}</button></section></section>
 <section><h3>{{t.history}}</h3><article v-for="p in history" :key="p.revision" class="preparation-history"><h4>{{p.id}} / {{p.revision}} · {{p.updatedAt}}</h4><p>{{p.actorId}} · {{bindingText(p.sourceBinding)}}</p><p class="preserve-text">{{p.purposeText||t.emptyPurpose}}</p><p class="preserve-text">{{p.changeReason}}</p><p>{{t.unverified}}</p><ul><li v-for="l in p.materialLeads" :key="l.lineId"><p class="preserve-text">{{l.name}} · {{l.sourceDescription||t.unknown}} · {{l.versionDescription||t.unknown}} · {{l.question||t.unknown}}</p></li></ul><p class="preserve-text">{{p.sourceSnapshot.visit.notes}}</p></article></section>
 </template>
</section>
</template>
<style scoped>.preparation-panel{padding:24px;margin:20px 0;overflow-wrap:anywhere}.preparation-panel header{display:flex;justify-content:space-between}.preparation-panel textarea,.preparation-panel input:not([type=checkbox]){display:block;width:100%}.preparation-lead,.preparation-history{border:1px solid #d8dee8;padding:12px;margin:12px 0}.preserve-text{white-space:pre-wrap}.preparation-panel p{line-height:1.7}</style>
